const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let {projects,issues,notes,milestones,activity}=window.Bootstrap;
let range='Week',type='project',newIssues=0;
function render(){ $('#stats').innerHTML=[['Total Projects',projects.length,'Projects in this workspace',''],['Total Tasks',issues.length,'Shared planning tasks',''],['In Progress',issues.filter(t=>t.status==='In Progress').length,'Tasks underway',''],['Completed',issues.filter(t=>t.status==='Done').length,'Tasks delivered','']].map(([label,value,desc,growth])=>`<article class="stat"><div class="stat-label">${label}<span>···</span></div><strong>${value}</strong><small><b>${growth}</b>${desc}</small></article>`).join('');renderProjects();renderTimeline();$('#note-list').innerHTML=notes.map(n=>`<article class="note"><strong>${esc(n.name)}</strong><p>${esc(n.description)}</p><div class="note-meta"><span>${esc(n.tag)}</span><span>Owner</span><time>${n.date}</time></div></article>`).join('');renderMilestones();$('#activity').innerHTML=activity.slice(0,3).map(a=>`<div class="activity"><span class="avatar">${a.initials}</span><div><strong>${esc(a.name)}</strong><p>${esc(a.description)}</p><small>${a.time}</small></div></div>`).join('')}
function renderProjects(){let q=$('#search').value.toLowerCase();let filtered=projects.filter(p=>(p.name+p.id+p.manager).toLowerCase().includes(q));$('#project-count').textContent=filtered.length;$('#project-list').innerHTML=filtered.length?filtered.map(project=>{const p={...project,...(window.Workspace?.projectPeople(project)||{})};return `<article class="project-card"><div class="project-top"><span>${esc(p.id)}</span><button data-detail="${esc(p.id)}">See details</button></div><label>Project Name</label><h3>${esc(p.name)}</h3><span class="badge">Active</span><div class="project-people"><div><label>Project Manager</label><div class="person"><span class="avatar">${esc(p.initials)}</span>${esc(p.manager)}</div></div><div><label>Team Lead</label><div class="person"><span class="avatar lavender">${esc(p.leadInitials||'?')}</span>${esc(p.lead)}</div></div></div><div class="project-team"><div class="avatars">${(p.memberInitials||[]).map(initials=>`<i>${esc(initials)}</i>`).join('')}</div>+${p.memberCount||0} people</div><label>Timeline</label><div class="dates"><span>${esc(p.date)}</span><span>${esc(p.end)}</span></div></article>`}).join(''):'<p class="empty">No projects match your search.</p>';}
function renderTimeline(){let labels=range==='Week'?['Sep 23','Sep 25','Today','Sep 30']:range==='Month'?['Sep 1','Sep 10','Today','Sep 30']:['Jul 1','Aug 1','Sep 1','Sep 30'];let scale=range==='Week'?1:range==='Month'?.72:.45;$('#timeline').innerHTML=`<div class="axis">${labels.map(l=>l==='Today'?'<b>Today</b>':`<span>${l}</span>`).join('')}</div>`+issues.map((i,j)=>`<div class="issue-row"><div class="issue-name"><strong>${esc(i.id)}</strong>${esc(i.status)}</div><div class="track"><button class="bar ${i.color}" style="left:${i.start*scale}%;width:${Math.max(22,i.width*scale)}%" data-issue="${j}" title="${esc(i.name)}"><span class="mini-avatar">KL</span><span>${esc(i.id)} · ${esc(i.name)}<small>${esc(i.status)} · September 2026</small></span></button></div></div>`).join('')}
function renderMilestones(){let months=parseInt($('#milestone-range').value);let cutoff=new Date('2026-09-29T12:00:00');cutoff.setMonth(cutoff.getMonth()+months);if($('#milestone-range').value==='1 Year')cutoff.setFullYear(2027);$('#milestone-list').innerHTML=milestones.filter(m=>new Date(m.date)<=cutoff).sort((a,b)=>a.date.localeCompare(b.date)).map(m=>`<div class="milestone"><span class="milestone-icon">⚑</span><div><strong>${esc(m.name)}</strong><small>${esc(m.project)}</small></div><time>${new Date(m.date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric'})}</time></div>`).join('')||'<p class="empty">No milestones in this range.</p>'}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function openCreate(t){type=t;$('#dialog-title').textContent={project:'New project',issue:'Create issue',milestone:'Schedule milestone',sprint:'Plan sprint',note:'Add note'}[t];$('#fields').innerHTML=`<label for="name">${t==='note'?'Title':'Name'}</label><input id="name" name="name" required maxlength="100" placeholder="${t==='project'?'e.g. Customer portal redesign':'Give it a clear name'}">`+(t==='note'?'<label for="description">Note</label><textarea id="description" name="description" required placeholder="What should the team know?"></textarea>':'<label for="date">'+(t==='sprint'?'Sprint start date':'Target date')+'</label><input type="date" id="date" name="date" required value="2026-09-30">');$('#submit').classList.remove('hidden');$('#cancel').textContent='Cancel';$('#dialog').showModal()}
function detail(title,html){$('#dialog-title').textContent=title;$('#fields').innerHTML=`<div class="detail">${html}</div>`;$('#submit').classList.add('hidden');$('#cancel').textContent='Close';$('#dialog').showModal()}
document.addEventListener('click',e=>{let create=e.target.closest('[data-create]');if(create)openCreate(create.dataset.create);let p=e.target.closest('[data-detail]');if(p){let item=projects.find(x=>x.id===p.dataset.detail);detail(item.name,`<p><b>${esc(item.id)}</b> · Active</p><p>Project manager: ${esc(item.manager)}<br>Team lead: ${esc(item.lead)}<br>Timeline: ${esc(item.date)} – ${esc(item.end)}</p><p>${item.team+4} team members are working on this project.</p>`)}let issue=e.target.closest('[data-issue]');if(issue){let i=issues[Number(issue.dataset.issue)];detail(i.id,`<p><b>${esc(i.name)}</b></p><p>Status: ${i.status}<br>Assignee: Kiara Laras<br>Project: Revenue Insights Revamp</p>`)} });
$('#form').addEventListener('submit',async e=>{e.preventDefault();let data=new FormData(e.target),name=data.get('name').trim(),date=data.get('date');if(!name)return;let displayDate=date?new Date(date+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'}):'';if(type==='project')projects.unshift({id:crypto.randomUUID(),name,manager:'Bin Li',lead:'Kiara Laras',initials:'BL',team:0,date:'Sep 29, 2026',end:displayDate});if(type==='issue'){newIssues++;issues.push({id:'RFC-'+(106+newIssues),name,status:'Todo',color:'blue',start:10,width:65})}if(type==='note')notes.unshift({id:crypto.randomUUID(),name,description:data.get('description'),tag:'New',date:'Sep 29'});if(type==='milestone'||type==='sprint')milestones.push({id:crypto.randomUUID(),name:type==='sprint'?'Sprint: '+name:name,project:'Studio workspace',date});activity.unshift({initials:'BL',name:'You created a '+type,description:name,time:'Just now'});try{await window.Workspace?.persist();render();$('#dialog').close();toast(type.charAt(0).toUpperCase()+type.slice(1)+' created')}catch(error){toast(error.message)}});
$('#close').onclick=$('#cancel').onclick=()=>$('#dialog').close();$('#search').oninput=renderProjects;$('#range').onclick=e=>{if(e.target.tagName!=='BUTTON')return;range=e.target.textContent;$('#range').querySelectorAll('button').forEach(b=>b.classList.toggle('active',b===e.target));renderTimeline()};$('#milestone-range').onchange=renderMilestones;$('#menu').onclick=()=>document.body.classList.toggle('collapsed');$('#refresh').onclick=()=>location.reload();document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-view]').forEach(n=>n.classList.toggle('selected',n===b));let section=b.dataset.view;if(section==='overview')window.scrollTo({top:0,behavior:'smooth'});else $('#'+section).scrollIntoView({behavior:'smooth'});if(innerWidth<980)document.body.classList.remove('collapsed')});render();
